{"code":"const searchResult = await callTool('search_flights', { from: 'BLR', to: 'SYD', maxPrice: 40000 });
const flights = searchResult.flights || [];
// get baggage policies in parallel
const baggagePromises = flights.map(f => callTool('get_baggage_policy', { flightId: f.id }));
const baggageResults = await Promise.all(baggagePromises);
// combine
const combined = flights.map((f, idx) => ({
  id: f.id,
  airline: f.airline,
  price: f.price,
  checkedKg: baggageResults[idx].checkedKg
}));
// filter >=20kg
const filtered = combined.filter(item => item.checkedKg >= 20);
// take three cheapest (already sorted by price from search)
const topThree = filtered.slice(0, 3);
return { options: topThree, sampleData: true };"}

